// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Unit tests proving armed tasks fire exactly when due
// Flo: arm task > feed fixed clock > assert due verdict, counters, errors
// I/O: Task specs + fake local time > pass or fail
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("tk-task-armz.zig");
const tszz = std.testing; const armTask = armz.armTask; const ArmError = armz.ArmError;
var test_iozz_impl = std.Io.Threaded.init_single_threaded; const iozz: std.Io = test_iozz_impl.io();
fn atzzMinu(year: u16, mont: u8, dayz: u8, hour: u8, minu: u8, wday: u8) time.Local { return .{ .year = year, .month = mont, .day = dayz, .hour = hour, .minute = minu, .second = 0, .weekday = wday, .minute_stamp = time.daysFromCivil(year, mont, dayz) * 1440 + @as(i64, hour) * 60 + @as(i64, minu) }; }
test "armTask accepts each time type" { const cron = try armTask(.{ .id = "a", .type = "cron", .sche = "0 2 * * *", .run = "x" }); try tszz.expectEqualStrings("cron", cron.typeName()); const puls = try armTask(.{ .id = "b", .type = "puls", .sche = "5s", .run = "x" }); try tszz.expectEqual(@as(u64, 5000), puls.kind.pulse); const once = try armTask(.{ .id = "c", .type = "once", .sche = "260714_0230", .run = "x" }); try tszz.expectEqualStrings("once", once.typeName()); const sola = try armTask(.{ .id = "d", .type = "sola", .sche = "sunset-30", .run = "x" }); try tszz.expectEqual(@as(i32, -30), sola.kind.solar.offset_min); }
test "armTask surfaces a bad schedule as an error, not a silent no-fire" { try tszz.expectError(ArmError.BadCron, armTask(.{ .id = "a", .type = "cron", .sche = "abc * * * *", .run = "x" })); try tszz.expectError(ArmError.BadCron, armTask(.{ .id = "a", .type = "cron", .sche = "0 99 * * *", .run = "x" })); try tszz.expectError(ArmError.BadPulse, armTask(.{ .id = "a", .type = "puls", .sche = "nope", .run = "x" })); try tszz.expectError(ArmError.BadPulse, armTask(.{ .id = "a", .type = "puls", .sche = "10", .run = "x" })); try tszz.expectError(ArmError.BadOnce, armTask(.{ .id = "a", .type = "once", .sche = "261301", .run = "x" })); try tszz.expectError(ArmError.BadSolar, armTask(.{ .id = "a", .type = "sola", .sche = "noon", .run = "x" })); }
test "S5 probe types arm for real, reporting their own type name" { const case = [_]struct { kind: []const u8, sche: ?[]const u8 }{ .{ .kind = "tcpr", .sche = "127.0.0.1:3000" }, .{ .kind = "webs", .sche = "http://localhost:3000/health" }, .{ .kind = "disk", .sche = "C:\\<10GB" }, .{ .kind = "proc", .sche = "node.exe" }, .{ .kind = "live", .sche = "auto-task.exe" }, .{ .kind = "idle", .sche = "15m" }, .{ .kind = "powe", .sche = "battery" }, .{ .kind = "mail", .sche = null } }; for (case) |item| { const arme = try armTask(.{ .id = "x", .type = item.kind, .sche = item.sche, .run = "y" }); try tszz.expectEqualStrings(item.kind, arme.typeName()); try tszz.expect(arme.probeState() != null); } }
test "a bad probe spec is an ArmError, not a silently dead task" { try tszz.expectError(ArmError.BadPort, armTask(.{ .id = "a", .type = "tcpr", .sche = "host:0", .run = "x" })); try tszz.expectError(ArmError.BadUrl, armTask(.{ .id = "a", .type = "webs", .sche = "https://x.com", .run = "x" })); try tszz.expectError(ArmError.BadSize, armTask(.{ .id = "a", .type = "disk", .sche = "C:\\ 10GB", .run = "x" })); try tszz.expectError(ArmError.BadProc, armTask(.{ .id = "a", .type = "proc", .sche = "C:\\x\\y.exe", .run = "x" })); try tszz.expectError(ArmError.BadDuration, armTask(.{ .id = "a", .type = "idle", .sche = "soon", .run = "x" })); try tszz.expectError(ArmError.BadPowerSpec, armTask(.{ .id = "a", .type = "powe", .sche = "maybe", .run = "x" })); try tszz.expectError(ArmError.NeedsSpec, armTask(.{ .id = "a", .type = "tcpr", .sche = null, .run = "x" })); }
test "every type in store.TYPES has a real arm path — none fall through" { const help = struct { fn typeSpec(kind: []const u8) ?[]const u8 { if (std.mem.eql(u8, kind, "cron")) return "0 2 * * *"; if (std.mem.eql(u8, kind, "puls")) return "30s"; if (std.mem.eql(u8, kind, "once")) return "260714_0230"; if (std.mem.eql(u8, kind, "sola")) return "sunset-30"; if (std.mem.eql(u8, kind, "even")) return "E:\\x"; if (std.mem.eql(u8, kind, "flag")) return "file:E:\\go.txt"; if (std.mem.eql(u8, kind, "queu")) return "E:\\q"; if (std.mem.eql(u8, kind, "link")) return "after:parent"; if (std.mem.eql(u8, kind, "tcpr")) return "3000"; if (std.mem.eql(u8, kind, "webs")) return "localhost/health"; if (std.mem.eql(u8, kind, "disk")) return "C:\\<10GB"; if (std.mem.eql(u8, kind, "proc")) return "node.exe"; if (std.mem.eql(u8, kind, "live")) return "node.exe"; if (std.mem.eql(u8, kind, "idle")) return "15m"; if (std.mem.eql(u8, kind, "powe")) return "battery"; return null; } }; for (stor.TYPE_LIST) |kind| { const arme = try armTask(.{ .id = "t", .type = kind, .sche = help.typeSpec(kind), .run = "x" }); try tszz.expectEqualStrings(kind, arme.typeName()); } }
test "chai: no sche = boot start; cron / interval / solar start it; a manual fire is latched" { var boot = try armTask(.{ .id = "c", .type = "chai", .ids = &.{"x"} }); try tszz.expectEqualStrings("chai", boot.typeName()); try tszz.expect(boot.isChain() and boot.chainBoots()); const word = try armTask(.{ .id = "c", .type = "chai", .sche = "boot", .ids = &.{"x"} }); try tszz.expect(word.chainBoots()); try tszz.expect(!boot.takeChainHand()); try tszz.expect(boot.requestHand()); try tszz.expect(boot.takeChainHand()); try tszz.expect(!boot.takeChainHand()); var cron = try armTask(.{ .id = "c", .type = "chai", .sche = "30 7 * * *", .ids = &.{"x"} }); try tszz.expect(!cron.chainBoots()); try tszz.expect(cron.due(iozz, atzzMinu(2026, 7, 14, 7, 30, 2), 0, null)); try tszz.expect(!cron.due(iozz, atzzMinu(2026, 7, 14, 7, 31, 2), 0, null)); var puls = try armTask(.{ .id = "c", .type = "chai", .sche = "6h", .ids = &.{"x"} }); try tszz.expect(!puls.due(iozz, atzzMinu(2026, 7, 14, 7, 30, 2), 1_000, null)); try tszz.expect(puls.due(iozz, atzzMinu(2026, 7, 14, 13, 30, 2), 1_000 + 6 * 3_600_000, null)); const sunz = try armTask(.{ .id = "c", .type = "chai", .sche = "sunset-30", .ids = &.{"x"} }); try tszz.expect(!sunz.chainBoots()); try tszz.expectError(ArmError.BadChain, armTask(.{ .id = "c", .type = "chai", .sche = "nope", .ids = &.{"x"} })); try tszz.expectError(ArmError.BadChain, armTask(.{ .id = "c", .type = "chai", .sche = "260714_0230", .ids = &.{"x"} })); }
test "S3 types now arm for real, reporting their own type name" { const case = [_]struct { kind: []const u8, sche: ?[]const u8 }{ .{ .kind = "boot", .sche = null }, .{ .kind = "hand", .sche = null }, .{ .kind = "even", .sche = "E:\\x" }, .{ .kind = "flag", .sche = "file:E:\\go.txt" }, .{ .kind = "queu", .sche = "E:\\q" } }; for (case) |item| { const arme = try armTask(.{ .id = "x", .type = item.kind, .sche = item.sche, .run = "y" }); try tszz.expectEqualStrings(item.kind, arme.typeName()); } }
test "S3 schedule errors surface, not silently never fire" { try tszz.expectError(ArmError.NeedsPath, armTask(.{ .id = "a", .type = "even", .run = "x" })); try tszz.expectError(ArmError.NeedsPath, armTask(.{ .id = "a", .type = "queu", .sche = "  ", .run = "x" })); try tszz.expectError(ArmError.BadFlagPrefix, armTask(.{ .id = "a", .type = "flag", .sche = "E:\\go.txt", .run = "x" })); }
test "requestHand only latches a hand task" { var hand = try armTask(.{ .id = "a", .type = "hand", .run = "x" }); try tszz.expect(hand.requestHand()); try tszz.expect(hand.due(iozz, atzzMinu(2026, 8, 17, 12, 0, 1), 0, null)); try tszz.expect(!hand.due(iozz, atzzMinu(2026, 8, 17, 12, 0, 1), 0, null)); var cron = try armTask(.{ .id = "b", .type = "cron", .sche = "0 2 * * *", .run = "x" }); try tszz.expect(!cron.requestHand()); var boot = try armTask(.{ .id = "c", .type = "boot", .run = "x" }); try tszz.expect(!boot.requestHand()); }
test "boot fires on the first tick, hand never does" { var boot = try armTask(.{ .id = "a", .type = "boot", .run = "x" }); const nowz = atzzMinu(2026, 8, 17, 12, 0, 1); try tszz.expect(boot.due(iozz, nowz, 1000, null)); try tszz.expect(!boot.due(iozz, nowz, 2000, null)); var hand = try armTask(.{ .id = "b", .type = "hand", .run = "x" }); var tick: u32 = 0; while (tick < 50) : (tick += 1) try tszz.expect(!hand.due(iozz, nowz, @intCast(tick * 1000), null)); }
test "claimedFile is empty for everything except queu" { const cron = try armTask(.{ .id = "a", .type = "cron", .sche = "0 2 * * *", .run = "x" }); try tszz.expectEqualStrings("", cron.claimedFile()); const boot = try armTask(.{ .id = "b", .type = "boot", .run = "x" }); try tszz.expectEqualStrings("", boot.claimedFile()); const queu = try armTask(.{ .id = "c", .type = "queu", .sche = "E:\\q", .run = "x" }); try tszz.expectEqualStrings("", queu.claimedFile()); }
test "cron fires ONCE per matching minute, not 60 times" { var arme = try armTask(.{ .id = "a", .type = "cron", .sche = "30 14 * * *", .run = "x" }); const hitz = atzzMinu(2026, 8, 17, 14, 30, 1); var fire: u32 = 0; var tick: u32 = 0; while (tick < 60) : (tick += 1) { if (arme.due(iozz, hitz, 0, null)) fire += 1; } try tszz.expectEqual(@as(u32, 1), fire); const tomo = atzzMinu(2026, 8, 18, 14, 30, 2); try tszz.expect(arme.due(iozz, tomo, 0, null)); }
test "cron does not fire on a non-matching minute" { var arme = try armTask(.{ .id = "a", .type = "cron", .sche = "30 14 * * *", .run = "x" }); try tszz.expect(!arme.due(iozz, atzzMinu(2026, 8, 17, 14, 29, 1), 0, null)); try tszz.expect(!arme.due(iozz, atzzMinu(2026, 8, 17, 13, 30, 1), 0, null)); try tszz.expect(arme.due(iozz, atzzMinu(2026, 8, 17, 14, 30, 1), 0, null)); }
test "pulse does not fire on its first tick — no restart stampede" { var arme = try armTask(.{ .id = "a", .type = "puls", .sche = "5s", .run = "x" }); const nowz = atzzMinu(2026, 8, 17, 12, 0, 1); try tszz.expect(!arme.due(iozz, nowz, 1_000_000, null)); try tszz.expect(!arme.due(iozz, nowz, 1_004_999, null)); try tszz.expect(arme.due(iozz, nowz, 1_005_000, null)); try tszz.expect(!arme.due(iozz, nowz, 1_005_001, null)); try tszz.expect(arme.due(iozz, nowz, 1_010_000, null)); }
test "pulse measures from the last fire, so a slow task does not stack fires" { var arme = try armTask(.{ .id = "a", .type = "puls", .sche = "5s", .run = "x" }); const nowz = atzzMinu(2026, 8, 17, 12, 0, 1); try tszz.expect(!arme.due(iozz, nowz, 0, null)); try tszz.expect(arme.due(iozz, nowz, 5_000, null)); var fire: u32 = 0; if (arme.due(iozz, nowz, 35_000, null)) fire += 1; if (arme.due(iozz, nowz, 35_001, null)) fire += 1; try tszz.expectEqual(@as(u32, 1), fire); }
test "once fires exactly once, ever" { const targ = time.daysFromCivil(2026, 8, 17) * 1440 + 12 * 60; var arme = try armTask(.{ .id = "a", .type = "once", .sche = "260817_1200", .run = "x" }); try tszz.expectEqual(targ, arme.kind.once); try tszz.expect(!arme.due(iozz, atzzMinu(2026, 8, 17, 11, 59, 1), 0, null)); try tszz.expect(arme.due(iozz, atzzMinu(2026, 8, 17, 12, 0, 1), 0, null)); try tszz.expect(!arme.due(iozz, atzzMinu(2026, 8, 17, 12, 0, 1), 0, null)); try tszz.expect(!arme.due(iozz, atzzMinu(2026, 8, 17, 12, 1, 1), 0, null)); try tszz.expect(!arme.due(iozz, atzzMinu(2027, 8, 17, 12, 0, 1), 0, null)); }
test "once does not fire for a long-past target" { var arme = try armTask(.{ .id = "a", .type = "once", .sche = "250101_0000", .run = "x" }); try tszz.expect(!arme.due(iozz, atzzMinu(2026, 8, 17, 12, 0, 1), 0, null)); }
test "solar never fires without a lat/lng config" { var arme = try armTask(.{ .id = "a", .type = "sola", .sche = "sunrise", .run = "x" }); try tszz.expect(!arme.due(iozz, atzzMinu(2026, 8, 17, 5, 30, 1), 1_755_000_000_000, null)); }
test "unsupported types never fire" { var arme = try armTask(.{ .id = "a", .type = "tcpr", .sche = "tcp:1.2.3.4:80", .run = "x" }); var tick: u32 = 0; while (tick < 100) : (tick += 1) { try tszz.expect(!arme.due(iozz, atzzMinu(2026, 8, 17, 12, @intCast(tick % 60), 1), @intCast(tick * 1000), null)); } }
test "markFired tracks counters" { var arme = try armTask(.{ .id = "a", .type = "cron", .sche = "* * * * *", .run = "x" }); try tszz.expectEqual(@as(u32, 0), arme.fire_count); arme.markFired(12345); arme.markFired(23456); try tszz.expectEqual(@as(u32, 2), arme.fire_count); try tszz.expectEqual(@as(i64, 23456), arme.last_fire_ms); }
test "nextFireStamp gives the UI something to show" { var cron = try armTask(.{ .id = "a", .type = "cron", .sche = "0 2 * * *", .run = "x" }); const nowz = atzzMinu(2026, 8, 17, 3, 0, 1); const next = cron.nextFireStamp(nowz).?; const nloc = time.localFromMinuteStamp(next); try tszz.expectEqual(@as(u8, 2), nloc.hour); try tszz.expectEqual(@as(u8, 18), nloc.day); var once = try armTask(.{ .id = "b", .type = "once", .sche = "260817_1200", .run = "x" }); try tszz.expect(once.nextFireStamp(nowz) != null); once.fired = true; try tszz.expect(once.nextFireStamp(nowz) == null); }
test "wildcard cron fires every minute but only once each" { var arme = try armTask(.{ .id = "a", .type = "cron", .sche = "* * * * *", .run = "x" }); var fire: u32 = 0; var minu: u8 = 0; while (minu < 3) : (minu += 1) { const loca = atzzMinu(2026, 8, 17, 12, minu, 1); var tick: u32 = 0; while (tick < 10) : (tick += 1) { if (arme.due(iozz, loca, 0, null)) fire += 1; } } try tszz.expectEqual(@as(u32, 3), fire); }
